S = input()

ans = "Yes"

word_list = [0] * 26

for s in S:
    word_list[ord(s) - ord("a")] += 1

frequency_count = {}

for count in word_list:
    if count > 0:
        if count in frequency_count:
            frequency_count[count] += 1
        else:
            frequency_count[count] = 1

for f in frequency_count.values():
    if f != 0 and f != 2:
        ans = "No"
        break

print(ans)
